const req = $json;
const body = req.body ?? req;
const headers = req.headers ?? {};
const required = ['version','correlation_id','source','actor','target','action','timestamp'];
const missing = required.filter(k => body[k] === undefined || body[k] === null || body[k] === '');
if (missing.length) {
  return [{json:{route:'respond',ok:false,status:'blocked',reason:'missing_fields',missing,correlation_id:body.correlation_id ?? null,timestamp:new Date().toISOString()}}];
}
if (body.target !== 'github-sync') {
  return [{json:{route:'respond',ok:false,status:'blocked',reason:'target_not_allowed',correlation_id:body.correlation_id,timestamp:new Date().toISOString()}}];
}
const store = $getWorkflowStaticData('global');
store.seen = Array.isArray(store.seen) ? store.seen : [];
if (store.seen.includes(body.correlation_id)) {
  return [{json:{route:'respond',ok:false,status:'blocked',reason:'duplicate_correlation_id',correlation_id:body.correlation_id,timestamp:new Date().toISOString()}}];
}
return [{json:{...body,headers,_validated:true}}];

const x = $json;
if (x.route === 'respond') return [{json:x}];

const registry = {
  'repo.inspect':'R0',
  'repo.read_file':'R0',
  'repo.list_prs':'R0',
  'repo.list_issues':'R0',
  'repo.compare_refs':'R0',
  'repo.health_summary':'R0',
  'repo.create_branch':'R1',
  'repo.create_draft_file':'R1',
  'repo.open_draft_pr':'R1',
  'repo.create_issue':'R1',
  'repo.update_tracked_file':'R2',
  'repo.modify_workflow':'R2',
  'repo.modify_integration_config':'R2',
  'repo.merge_pr':'R3',
  'repo.delete_file':'R3',
  'repo.delete_branch':'R3',
  'repo.change_permissions':'R3',
  'repo.change_visibility':'R3',
  'secrets.write':'R3',
  'production.deploy':'R3'
};

const risk = typeof x.action === 'string' && Object.hasOwn(registry, x.action) ? registry[x.action] : null;
if (!risk) return [{json:{route:'respond',ok:false,status:'blocked',reason:'unknown_action',correlation_id:x.correlation_id,timestamp:new Date().toISOString()}}];
if (risk === 'R3') return [{json:{route:'respond',ok:false,status:'blocked',reason:'prohibited_action',risk_class:risk,correlation_id:x.correlation_id,timestamp:new Date().toISOString()}}];
if (risk === 'R1' || risk === 'R2') return [{json:{route:'respond',ok:false,status:'blocked',reason:'approval_required',risk_class:risk,correlation_id:x.correlation_id,timestamp:new Date().toISOString()}}];

const base = 'https://api.github.com/repos/botbikamordehai2-sketch/github-sync';
const p = x.payload ?? {};
let requestUrl;

const safeRef = v => typeof v === 'string' && /^[A-Za-z0-9._\/-]{1,200}$/.test(v);
const safePath = v => typeof v === 'string' && v.length > 0 && v.length <= 500 && !v.includes('..') && !v.startsWith('/');

switch (x.action) {
  case 'repo.inspect':
  case 'repo.health_summary':
    requestUrl = base;
    break;
  case 'repo.read_file':
    if (!safePath(p.path)) return [{json:{route:'respond',ok:false,status:'blocked',reason:'invalid_path',risk_class:risk,correlation_id:x.correlation_id,timestamp:new Date().toISOString()}}];
    requestUrl = base + '/contents/' + p.path.split('/').map(encodeURIComponent).join('/');
    if (p.ref) {
      if (!safeRef(p.ref)) return [{json:{route:'respond',ok:false,status:'blocked',reason:'invalid_ref',risk_class:risk,correlation_id:x.correlation_id,timestamp:new Date().toISOString()}}];
      requestUrl += '?ref=' + encodeURIComponent(p.ref);
    }
    break;
  case 'repo.list_prs':
    requestUrl = base + '/pulls?state=' + encodeURIComponent(p.state ?? 'open') + '&per_page=30';
    break;
  case 'repo.list_issues':
    requestUrl = base + '/issues?state=' + encodeURIComponent(p.state ?? 'open') + '&per_page=30';
    break;
  case 'repo.compare_refs':
    if (!safeRef(p.base) || !safeRef(p.head)) return [{json:{route:'respond',ok:false,status:'blocked',reason:'invalid_compare_refs',risk_class:risk,correlation_id:x.correlation_id,timestamp:new Date().toISOString()}}];
    requestUrl = base + '/compare/' + encodeURIComponent(p.base) + '...' + encodeURIComponent(p.head);
    break;
  default:
    return [{json:{route:'respond',ok:false,status:'blocked',reason:'unknown_action',correlation_id:x.correlation_id,timestamp:new Date().toISOString()}}];
}

return [{json:{...x,route:'execute',risk_class:risk,decision:'allowed',request_url:requestUrl}}];

const response = $json;
const ctx = $('Policy Gate + GitHub Router').item.json;
const statusCode = response.statusCode;
const body = response.body ?? null;

// Missing status is never success (including transport errors).
const ok = Number.isInteger(statusCode) && statusCode >= 200 && statusCode < 300 && !response.error;
const result = ok ? body : {statusCode: Number.isInteger(statusCode) ? statusCode : null,error:response.error ?? body ?? 'missing_http_status'};

const store = $getWorkflowStaticData('global');
store.audit = Array.isArray(store.audit) ? store.audit : [];
const audit = {
  audit_id: crypto.randomUUID ? crypto.randomUUID() : String(Date.now()),
  correlation_id: ctx.correlation_id,
  agent_id: 'chatgpt-n8n-bridge-v1',
  actor: ctx.actor,
  target: ctx.target,
  action: ctx.action,
  risk_class: ctx.risk_class,
  decision: ctx.decision,
  approval_status: 'not_required',
  result_status: ok ? 'success' : 'error',
  timestamp: new Date().toISOString()
};
store.audit.push(audit);
if (store.audit.length > 500) store.audit = store.audit.slice(-500);
if (ok) {
  store.seen = Array.isArray(store.seen) ? store.seen : [];
  store.seen.push(ctx.correlation_id);
  if (store.seen.length > 500) store.seen = store.seen.slice(-500);
}

return [{json:{
  ok,
  correlation_id:ctx.correlation_id,
  status:ok ? 'completed' : 'error',
  action:ctx.action,
  risk_class:ctx.risk_class,
  approval:'not_required',
  result,
  audit_id:audit.audit_id,
  timestamp:new Date().toISOString()
}}];

const x = $json;
const store = $getWorkflowStaticData('global');
store.audit = Array.isArray(store.audit) ? store.audit : [];
const audit = {
  audit_id: String(Date.now()) + '-blocked',
  correlation_id: x.correlation_id ?? null,
  agent_id: 'chatgpt-n8n-bridge-v1',
  actor: x.actor ?? null,
  target: x.target ?? null,
  action: x.action ?? null,
  risk_class: x.risk_class ?? null,
  decision: 'blocked',
  reason: x.reason ?? 'policy_block',
  approval_status: x.reason === 'approval_required' ? 'required' : 'not_applicable',
  timestamp: new Date().toISOString()
};
store.audit.push(audit);
if (store.audit.length > 500) store.audit = store.audit.slice(-500);
return [{json:{...x,audit_id:audit.audit_id}}];
